plugins {
    `java`
}

group = "com.hfturay"
version = "1.0.0"
val serverDir = "C:/Users/Hassa/server 2.0" 

repositories {
    mavenCentral()
    maven("https://repo.papermc.io/repository/maven-public/") // Paper repo
    maven("https://maven.elmakers.com/repository/")
    
}

dependencies {
    compileOnly("io.papermc.paper:paper-api:1.21.1-R0.1-SNAPSHOT") // Paper API
    compileOnly("com.elmakers.mine.bukkit:EffectLib:10.10")
}

// Apply a specific Java toolchain to ease working on different environments.
java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

tasks.named<Test>("test") {
    // Use JUnit Platform for unit tests.
    useJUnitPlatform()
}

tasks.register<Copy>("deploy") {
    dependsOn("build")
    from(layout.buildDirectory.dir("libs")) {
        include("${project.name}-${project.version}.jar")
    }
    into("$serverDir/plugins")

    doFirst {
        // delete older versions of this plugin to avoid duplicates
        delete(fileTree("$serverDir/plugins") {
            include("${project.name}-*.jar")
        })
    }
}





